/**
 * SpecRef Unequal Fittings Database
 * Standard: ASME B16.9 1993 — Factory-Made Wrought Buttwelding Fittings
 * Dimensions: mm | Weights: kg (approximate)
 * null = combination not tabulated in the standard
 */

import { ScheduleKey, ScheduleRecord, SCHEDULES } from "./fittingData";

// ─────────────────────────────────────────────────────────────────────────────
// INTERFACES
// ─────────────────────────────────────────────────────────────────────────────

export interface UnequalFittingSize {
  nps: string;           // e.g. "8 x 6"
  od_main_mm: number;    // outside diameter of run (main) pipe, mm
  od_outlet_mm: number;  // outside diameter of branch (outlet) pipe, mm
  length_mm: number;     // centre-to-end length, mm
}

export interface UnequalFittingType {
  label: string;
  standard: string;
  sizes: Record<string, UnequalFittingSize>;
  mainWallThickness_mm: Record<string, ScheduleRecord>;
  branchWallThickness_mm: Record<string, ScheduleRecord>;
  weight_kg: Record<string, ScheduleRecord>;
}

